 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    def separator_positions(axis):
        n = h if axis == 0 else w
        seqs = [grid[i] if axis == 0 else [grid[r][i] for r in range(h)] for i in range(n)]
        result=[]
        for i, seq in enumerate(seqs):
            counts=Counter(seq)
            if counts.most_common(1)[0][1] / len(seq) >= 0.95:
                result.append(i)
        return result

    def regular_step(pos):
        gaps=[b-a for a,b in zip(pos,pos[1:])]
        return Counter(gaps).most_common(1)[0][0] if gaps else 1

    rs, cs = separator_positions(0), separator_positions(1)
    if len(rs)<2 or len(cs)<2:
        return [[Counter(v for row in grid for v in row).most_common(1)[0][0]]]
    rp, cp = regular_step(rs), regular_step(cs)
    # use regular lattice; lines with a few marker pixels still meet the threshold
    rr=list(range(rs[0], h, rp))
    cc=list(range(cs[0], w, cp))
    lattice=[[grid[r][c] for c in cc] for r in rr]
    fill=Counter(v for row in grid for v in row).most_common(1)[0][0]

    # A symbol is a 2-by-2 block of matching colored junctions. Its top-left
    # junction determines its location in the reduced grid.
    symbols=[]
    for i in range(len(rr)-1):
        for j in range(len(cc)-1):
            v=lattice[i][j]
            if v != fill and lattice[i][j+1]==v and lattice[i+1][j]==v and lattice[i+1][j+1]==v:
                symbols.append((i,j,v))
    if not symbols:
        return [[fill]]
    r0,r1=min(i for i,j,v in symbols),max(i for i,j,v in symbols)
    c0,c1=min(j for i,j,v in symbols),max(j for i,j,v in symbols)
    out=[[fill for _ in range(c1-c0+1)] for _ in range(r1-r0+1)]
    for i,j,v in symbols:
        out[i-r0][j-c0]=v
    return out
